INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',106,'{"_type":"chat:Message","id":"-5124234082:1486","threadId":"telegram:-5124234082","text":"Pepa, by the way, we have many other sauces and many different liquids in our pantry.\n- We have a big 1 L bottle of soy sauce.\n- We have half a bottle of teriyaki, so probably 100 mL left.\n- We have half a bottle of rice vinegar, so probably I don''t like 300 mL of rice vinegar.\n- We have a 200 mL bottle of fish sauce.\n- We have Worcestershire sauce, which is pretty old but I guess it doesn''t get spoiled.\n- We have dumping sauce as well, which is almost over.\n- We have another 200 mL bottle of rice vinegar.\n- We have a small 100 mL bottle of argan oil.\n- We have a small 100 mL of liquid smoke.\n- We have 100 mL of molio ingles.\n- We have half a liter of sesame oil as well.\n Add all this to the pantry and take into consideration for meal suggestions","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Pepa, by the way, we have many other sauces and many different liquids in our pantry.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":86,"offset":85}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":86,"offset":85}}},{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"We have a big 1 L bottle of soy sauce.","position":{"start":{"line":2,"column":3,"offset":88},"end":{"line":2,"column":41,"offset":126}}}],"position":{"start":{"line":2,"column":3,"offset":88},"end":{"line":2,"column":41,"offset":126}}}],"position":{"start":{"line":2,"column":1,"offset":86},"end":{"line":2,"column":41,"offset":126}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"We have half a bottle of teriyaki, so probably 1