INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',118,'{"_type":"chat:Message","id":"-5124234082:1526","threadId":"telegram:-5124234082","text":"Je clarifie ce qu''on a reçu dans le panier :\n- 6 pommes\n- 4 kiwis\n- 3 poires\n- 2 citrons\n- 3 petites bananes\n- 4 pommes de terre\n- L''équivalent de 4 carottes\n- 2 courgettes\n- 1 concombre\n- 1 tête d''ail\n- 1 poireau\n- 1 tomate cœur de bœuf\n- Une salade verte à manger vite, parce qu''elle n''est pas super en point\n\n\nEt à ça on rajoute ce qu''on avait déjà dans le frigidaire et dans les fruits et légumes, c''est-à-dire :\n- Un demi oignon\n- 3 citrons verts\n- 3 carottes\n- Une courgette\n- Un concombre\n- Demie 3 tomates\n- Un demi chou vert pour coleslaw\n- Une salade verte\n- Une pomme\n- 3 pommes de terre\n- 2 oignons jaunes\n- 2 têtes d''ail\n- 2 oignons rouges\n- 3 citrons\n + les 6 oeufs frais qu’on vient de recevoir","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je clarifie ce qu''on a reçu dans le panier :","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":45,"offset":44}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":45,"offset":44}}},{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"6 pommes","position":{"start":{"line":2,"column":3,"offset":47},"end":{"line":2,"column":11,"offset":55}}}],"position":{"start":{"line":2,"column":3,"offset":47},"end":{"line":2,"column":11,"offset":55}}}],"position":{"start":{"line":2,"column":1,"offset":45},"end":{"line":2,"column":11,"offset":55}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"4 kiwis","position":{"start":{"line":3,"column":3,"offset":58},"end":{"line":3,"column":10,"offset":65}}}],"position":{"start":{"line":3,"colum