INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',175,'{"_type":"chat:Message","id":"-5124234082:1692","threadId":"telegram:-5124234082","text":"On a choisi de faire des gyoza qu’on a au congel. J’ai aussi fait un batch de riz. Et des boquerones et olives en aperitif","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"On a choisi de faire des gyoza qu’on a au congel. J’ai aussi fait un batch de riz. Et des boquerones et olives en aperitif","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":123,"offset":122}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":123,"offset":122}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":123,"offset":122}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-05-18T19:26:57.000Z","edited":false},"attachments":[],"isMention":false}',1779737214091);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',176,'{"_type":"chat:Message","id":"-5124234082:1695","threadId":"telegram:-5124234082","text":"Non ce midi on a mangé la moitié du curry de legumes, la feijoada est toujours au congel","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Non ce midi on a mangé la moitié du curry de legumes, la feijoada est toujours au congel","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":89,"offset":88}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":89,"offset":88}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":89,"offset":88}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-05-18T19:48:48.000Z","edited":false},"attachments":[],"isMention":false}',1779738526559);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',177,'{"_type":"chat:Message","id":"-5124234082:1698","threadId":"telegram:-5124234082","text":"On a une recette de dumplings dans la bibliothèque ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"On a une recette de dumplings dans la bibliothèque ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":53,"offset":52}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":53,"offset":52}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":53,"offset":52}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-05-18T20:19:14.000Z","edited":false},"attachments":[],"isMention":false}',1779740353502);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',178,'{"_type":"chat:Message","id":"-5124234082:1699","threadId":"telegram:-5124234082","text":"Garde cette recette pour faire des dumplings congelés :\n\nVoici une **recette simple, rapide et adaptée pour 24 dumplings déjà décongelés**, pour obtenir un dessous croustillant et une cuisson parfaite.\n\n⸻\n\n**🥟 Dumplings à la poêle (24 pièces, déjà décongelés)**\n\n**Ingrédients**\n\n24 dumplings décongelés\n2 à 3 c. à soupe d’huile végétale\n**80–100 ml d’eau** (≈ 1/3 tasse)\n(Optionnel) Sauce : soja + vinaigre de riz + huile de sésame + un peu de gingembre ou piment\n\n⸻\n\n**🔥 Préparation**\n\n**1) Dorer les dumplings**\n\nChauffe une grande poêle (ou deux moyennes) à feu moyen.\nAjoute 2–3 c. à soupe d’huile.\nPlace les 24 dumplings *sans les coller les uns aux autres*.\nLaisse dorer **2–3 minutes**, jusqu’à ce que le dessous soit bien doré.\n\n**2) Cuisson vapeur rapide**\n\nParce qu’ils sont décongelés, on met **moins d’eau** que d’habitude.\n\nVerse **80–100 ml d’eau** — juste assez pour couvrir très légèrement le fond.\nCouvre immédiatement.\nLaisse cuire **3–5 minutes** : ils doivent être chauds à cœur mais encore fermes.\n\n**3) Final croustillant**\n\nEnlève le couvercle.\nLaisse évaporer l’eau restante.\nLaisse croustiller **1–2 minutes** de plus.\n\n**4) Service**\n\nMélange une sauce express :\n2 c. à soupe de soja\n1 c. à soupe de vinaigre de riz\nquelques gouttes d’huile de sésame\n(optionnel) gingembre ou piment\n\n⸻\n\n**✔️ Résultat**\n\nDes dumplings **dorés dessous, tendres dessus**, parfaitement cuits malgré la décongélation.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Garde cette recette pour faire des dumplings congelés :","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":56,"offset":55}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":56,"offset":55}}},{"type":"paragraph","children":[{"type":"text","value":"Voici une ","position":{"start":{"line":3,"column":1,"offset":57},"end":{"line":3,"column":11,"offset":67}}},{"type":"strong","children":[{"type":"text","value":"recette simple, rapide et adaptée pour 24 dumplings déjà décongelés","position":{"start":{"line":3,"column":13,"offset":69},"end":{"line":3,"column":80,"offset":136}}}],"position":{"start":{"line":3,"column":11,"offset":67},"end":{"line":3,"column":82,"offset":138}}},{"type":"text","value":", pour obtenir un dessous croustillant et une cuisson parfaite.","position":{"start":{"line":3,"column":82,"offset":138},"end":{"line":3,"column":145,"offset":201}}}],"position":{"start":{"line":3,"column":1,"offset":57},"end":{"line":3,"column":145,"offset":201}}},{"type":"paragraph","children":[{"type":"text","value":"⸻","position":{"start":{"line":5,"column":1,"offset":203},"end":{"line":5,"column":2,"offset":204}}}],"position":{"start":{"line":5,"column":1,"offset":203},"end":{"line":5,"column":2,"offset":204}}},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"🥟 Dumplings à la poêle (24 pièces, déjà décongelés)","position":{"start":{"line":7,"column":3,"offset":208},"end":{"line":7,"column":55,"offset":260}}}],"position":{"start":{"line":7,"column":1,"offset":206},"end":{"line":7,"column":57,"offset":262}}}],"position":{"start":{"line":7,"column":1,"offset":206},"end":{"line":7,"column":57,"offset":262}}},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Ingrédients","position":{"start":{"line":9,"column":3,"offset":266},"end":{"line":9,"column":14,"offset":277}}}],"position":{"start":{"line":9,"column":1,"offset":264},"end":{"line":9,"column":16,"offset":279}}}],"position":{"start":{"line":9,"column":1,"offset":264},"end":{"line":9,"column":16,"offset":279}}},{"type":"paragraph","children":[{"type":"text","value":"24 dumplings décongelés\n2 à 3 c. à soupe d’huile végétale\n","position":{"start":{"line":11