INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',128,'{"_type":"chat:Message","id":"8641420749:240","threadId":"telegram:8641420749","text":"Imagine you need to prepare a report for an investment consultant that would take into account:\n- all our expenses\n- our liabilities\n- our current savings\n- the power that we have to save every month\n- our risk profile\n- everything\n- our existing investment\n\n\nThis guy would then basically prepare an investment strategy for us with several options, several scenarios based on our goal. Imagine you would prepare the perfect report as input for him. What would you include? What do you already have and what are you missing?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Imagine you need to prepare a report for an investment consultant that would take into account:","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":96,"offset":95}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":96,"offset":95}}},{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"all our expenses","position":{"start":{"line":2,"column":3,"offset":98},"end":{"line":2,"column":19,"offset":114}}}],"position":{"start":{"line":2,"column":3,"offset":98},"end":{"line":2,"column":19,"offset":114}}}],"position":{"start":{"line":2,"column":1,"offset":96},"end":{"line":2,"column":19,"offset":114}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"our liabilities","position":{"start":{"line":3,"column":3,"offset":117},"end":{"line":3,"column":18,"offset":132}}}],"position":{"start":{"line":3,"column":3,"offset":117},"end":{"line":3,"column":18,"offset":132}}}],"position":{"start":{"line":3,"column":1,"offset":115},"end":{"line":3,"column":18,